def num_islands_brute(grid):
    rows, cols = len(grid), len(grid[0])
    group = {}
    next_id = 0
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == '1':
                group[(r, c)] = next_id
                next_id += 1
    changed = True
    while changed:
        changed = False
        for r in range(rows):
            for c in range(cols):
                if grid[r][c] == '1':
                    for dr, dc in [(1,0),(0,1)]:
                        nr, nc = r+dr, c+dc
                        if nr<rows and nc<cols and grid[nr][nc]=='1' and group[(nr,nc)] != group[(r,c)]:
                            old, new = group[(nr,nc)], group[(r,c)]
                            for key in group:                              # repeated full scans to merge
                                if group[key] == old:
                                    group[key] = new
                            changed = True
    return len(set(group.values()))

